# ===== [VIA:PS-ACCEL:v0100] PS 20 加速器橋(批255 全樹導入;graceful 缺席零影響) =====
try {
    $VIAPSAccelProbe = $PSScriptRoot
    while ($VIAPSAccelProbe -and (Split-Path $VIAPSAccelProbe -Parent)) {
        $VIAPSAccelMod = Join-Path $VIAPSAccelProbe "supportive modules\VIA_PS_Accel_Module.ps1"
        if (Test-Path $VIAPSAccelMod) { . $VIAPSAccelMod; break }
        $VIAPSAccelProbe = Split-Path $VIAPSAccelProbe -Parent
    }
} catch { }
# ===== [VIA:PS-ACCEL:END] =====
$ErrorActionPreference = 'Stop'

# ---- 1) 定位 repo(優先 movies-dataset,退而求其次:目前目錄往下找)---------
$Repo = 'C:\Users\tonyk\movies-dataset\VeritasIntelligenceAnalytics'
if (-not (Test-Path -LiteralPath $Repo)) {
    $cand = Get-ChildItem -Directory -Recurse -Depth 2 -Filter 'VeritasIntelligenceAnalytics' -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($cand) { $Repo = $cand.FullName } else { Write-Output '找不到 VeritasIntelligenceAnalytics,請在 repo 上層執行'; return }
}
$Gov = Join-Path $Repo 'supportive modules\VIA_Governance_Runtime'
$Cge = Join-Path $Gov 'cge'
$BinDir = Join-Path $Repo 'bin'
foreach ($d in @($Gov, $Cge, $BinDir)) { if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d | Out-Null } }

