$EnginePath = Join-Path $Gov 'CGC_MDL001_CentralGovernanceEngine_v0400.py'
$PathsFile  = Join-Path $Cge 'ssot_paths.txt'
[System.IO.File]::WriteAllBytes($EnginePath, [System.Convert]::FromBase64String($EngineB64))
[System.IO.File]::WriteAllBytes($PathsFile,  [System.Convert]::FromBase64String($PathsB64))
Write-Output ('[解壓] ' + $EnginePath)

# ---- 3) 註冊 via-gov 指令(跟 via-mega/via-probe 同款,add-only) ------------
$CmdPath = Join-Path $BinDir 'via-gov.cmd'
$cmdBody = '@echo off' + [Environment]::NewLine + `
    'python "' + $EnginePath + '" --workdir "' + $Cge + '" %*'
[System.IO.File]::WriteAllText($CmdPath, $cmdBody, (New-Object System.Text.UTF8Encoding($false)))
Write-Output ('[註冊] via-gov  →  ' + $CmdPath)

# ---- 4) 自動定位 FNC-001 與 Extraction Matrix -------------------------------
$Fnc = Get-ChildItem -LiteralPath $Repo -Recurse -Filter 'InvestmentRegexPattern_VALIDATED*.py' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if (-not $Fnc) { $Fnc = Get-ChildItem -LiteralPath (Join-Path $env:USERPROFILE 'Downloads') -Recurse -Depth 3 -Filter 'InvestmentRegexPattern_VALIDATED*.py' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1 }
$Mx = @()
foreach ($root in @($Repo, (Join-Path $env:USERPROFILE 'Downloads'))) {
    $Mx += Get-ChildItem -LiteralPath $root -Recurse -Depth 4 -Filter 'VIA_Extraction_Matrix*.csv' -ErrorAction SilentlyContinue
}
$Mx = $Mx | Sort-Object LastWriteTime -Descending | Select-Object -First 1

# ---- 5) 組參數並執行(--commit 全流程;找不到的來源自動略過該參數)-----------
$argsList = @('"' + $EnginePath + '"', '--workdir', '"' + $Cge + '"',
              '--commit', '--fetch-tw',
              '--ssot-list', '"' + $PathsFile + '"',
              '--register-ssot', '"' + $Repo + '"')
if ($Fnc) { $argsList += @('--import-curated', '"' + $Fnc.FullName + '"'); Write-Output ('[FNC-001] ' + $Fnc.FullName) } else { Write-Output '[FNC-001] 未找到,略過 --import-curated' }
if ($Mx)  { $argsList += @('--import-matrix',  '"' + $Mx.FullName  + '"'); Write-Output ('[Matrix ] ' + $Mx.FullName) } else { Write-Output '[Matrix ] 未找到,略過 --import-matrix' }

$psi = New-Object System.Diagnostics.ProcessStartInfo
$psi.FileName = 'python'
$psi.Arguments = ($argsList -join ' ')
$psi.UseShellExecute = $false
$psi.RedirectStandardOutput = $true
$psi.RedirectStandardError = $true
$psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8
$p = [System.Diagnostics.Process]::Start($psi)
while (-not $p.StandardOutput.EndOfStream) { Write-Output $p.StandardOutput.ReadLine() }
$errTail = $p.StandardError.ReadToEnd()
$p.WaitForExit()
if ($errTail) { Write-Output $errTail }

# ---- 6) 開儀表板 -------------------------------------------------------------
$Dash = Join-Path $Cge 'VIA_CentralGovernance.html'
if (Test-Path -LiteralPath $Dash) { Start-Process $Dash }
Write-Output '=============================================================='
Write-Output ('完成。之後日常只要打:  via-gov --commit --fetch-tw   (dry-run 則省略 --commit)')
Write-Output ('治理 SSOT 位置: ' + $Cge)

